import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';

@Component({
  selector: 'notification-detail',
  templateUrl: 'notification-detail.html',
  styleUrls: ['./notification-detail.scss'],
})
export class NotificationDetailComponent {
  public notificationDetailWidgets = '';
  public messageId = '';
  constructor(
    public dxpComponentService: DxpComponentService,
    public route: ActivatedRoute,
    public router: Router,
    public cre: Credential,
    public cStore: CurrentStore
  ) {
    const params = this.route.snapshot.paramMap;
    this.messageId = params.get('messageId');
  }

  async ionViewDidEnter() {
    await this.dxpComponentService.onConnected();
    try {
      this.notificationDetailWidgets = `<dxp-notification-detail message-id="${this.messageId}"></dxp-notification-detail>`;
    } catch (err) {
      console.error('err', err);
    }
  }

  reloadSelectedMessage() {
    const payload = { action: 'MessageSelected' };
    window.postMessage({ ...payload }, window.location.origin);
    return this.router.navigate(['/notification']);
  }
}
