import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Credential } from '@rsApp/modules/auth-v2/providers/credential.service';
import { CurrentStore } from '@rsApp/modules/store/store.module';
import { DxpComponentService } from '@rsApp/modules/utils/providers/dxp.component.service';

@Component({
  selector: 'notification-page',
  templateUrl: 'notification-page.html',
  styleUrls: ['./notification-page.scss'],
})
export class NotificationPageComponent {
  public notificationWidgets = '';
  constructor(
    public dxpComponentService: DxpComponentService,
    public route: ActivatedRoute,
    public router: Router,
    public cre: Credential,
    public cStore: CurrentStore
  ) {}

  async ionViewDidEnter() {
    await this.dxpComponentService.onConnected();
    try {
      this.notificationWidgets = `<dxp-notification-page></dxp-notification-page>`;
    } catch (err) {
      console.error('err', err);
    }
  }

  returnHome() {
    return this.router.navigate(['tabs/home']);
  }
}
