import { NgModule } from '@angular/core';
import { Routes, RouterModule } from '@angular/router';
import { NotificationDetailComponent, NotificationModule, NotificationPageComponent } from './notification.module';

const routes: Routes = [
  {
    path: '',
    component: NotificationPageComponent,
  },
  {
    path: ':messageId',
    component: NotificationDetailComponent,
  },
];

@NgModule({
  imports: [RouterModule.forChild(routes), NotificationModule],
})
export class NotificationRoutingModule {}
